import chalk from 'chalk';
import { localDiff } from '../core/local-diff.js';
import { warnStrayFiles } from '../core/scanner.js';
import { snapshotExists } from '../core/snapshot.js';
import { loadState } from '../core/state.js';
import { loadCredentials, maskToken } from '../core/credentials.js';
import { webhookStatusLine } from './webhook.js';
import { displayPath } from '../core/workdir.js';
import { loadProjectConfig, configFileName } from '../core/project-config.js';
import { scanStatic, staticDiff, loadStaticSnapshot, unmanagedStaticNotice } from '../core/static.js';

export function registerStatus(program) {
  program
    .command('status')
    .description('Show working-directory status relative to the local snapshot (offline)')
    .action(async () => {
      const creds = loadCredentials();
      const state = loadState();

      // Same priority as resolveToken(): env first, then saved credentials.
      if (process.env.TGCLOUD_TOKEN) {
        console.log(chalk.dim(`Linked to ${maskToken(process.env.TGCLOUD_TOKEN)} (from env)`));
      } else if (creds?.token) {
        console.log(chalk.dim(`Linked to ${maskToken(creds.token)} (saved)`));
      } else {
        console.log(chalk.dim('Not linked to a bot yet.'));
      }

      if (state.last_known_revision != null) {
        console.log(chalk.dim(`Local revision: ${state.last_known_revision}`));
      }

      // The only network call in status; silent on failure.
      const whLine = await webhookStatusLine();
      if (whLine) console.log(whLine);

      if (!snapshotExists()) {
        console.log('\n' + chalk.yellow('Warning: ') +
          'No local snapshot. Run "tgcloud pull" or "tgcloud fetch" first.');
      }

      const diff = localDiff();

      if (diff.modified.length) {
        console.log(chalk.yellow('\nModified:'));
        for (const f of diff.modified) console.log(`  ${displayPath(f.path)}`);
      }

      if (diff.newLocal.length) {
        console.log(chalk.green('\nNew (not yet deployed):'));
        for (const f of diff.newLocal) console.log(`  ${displayPath(f.path)}`);
      }

      if (diff.remoteOnly.length) {
        console.log(chalk.red('\nDeleted locally (still in snapshot):'));
        for (const f of diff.remoteOnly) console.log(`  ${displayPath(f.path)}`);
      }

      const anyChanges = diff.modified.length + diff.newLocal.length + diff.remoteOnly.length;

      if (!anyChanges && diff.matched.length) {
        console.log(chalk.green('\nWorking directory clean.'));
      }

      warnStrayFiles();

      if (!anyChanges && !diff.matched.length) {
        console.log('\nNo files found. Run "tgcloud init" to scaffold a project.');
      }

      printStaticStatus();
    });
}

// Static: build output vs the static snapshot (hash diff, offline).
function printStaticStatus() {
  const block = loadProjectConfig().static;
  const snapshot = loadStaticSnapshot();
  if (!block) {
    if (snapshot) {
      console.log('\n' + unmanagedStaticNotice(snapshot, configFileName()).join('\n'));
    }
    return;
  }
  if (block.remove) {
    if (snapshot) console.log(chalk.red(`\nStatic: will be removed on push (${configFileName()}: "static": false).`));
    return;
  }
  const scan = scanStatic(block.source);
  const where = snapshot?.url ? ` → ${snapshot.url}` : '';
  console.log(chalk.bold(`\nStatic (${block.source}/${where})`));
  if (!scan) {
    console.log(chalk.yellow('Warning: ') + `folder "${block.source}/" not found — build the app first.`);
    return;
  }
  if (!Object.keys(scan.manifest).length) {
    console.log(chalk.yellow('Warning: ') + `folder "${block.source}/" is empty — build the app first.`);
    return;
  }
  const d = staticDiff(scan, block.config, snapshot);
  const line = (p) => `  ${block.source}/${p}`;
  if (d.modified.length) { console.log(chalk.yellow('Modified:')); d.modified.forEach((p) => console.log(line(p))); }
  if (d.added.length) { console.log(chalk.green(snapshot ? 'New (not yet deployed):' : 'Not yet deployed:')); d.added.forEach((p) => console.log(line(p))); }
  if (d.deleted.length) { console.log(chalk.red('Deleted locally (still deployed):')); d.deleted.forEach((p) => console.log(line(p))); }
  if (d.configChanged && snapshot) console.log(chalk.yellow('Modified:') + ` static config (${configFileName()})`);
  if (!d.changed) console.log(chalk.green(`Up to date (${d.unchanged} file${d.unchanged === 1 ? '' : 's'}).`));
  if (scan.nonNfc.length) {
    console.log(chalk.yellow('Warning: ') +
      `${scan.nonNfc.length} path${scan.nonNfc.length === 1 ? ' is' : 's are'} not NFC-normalized (e.g. ${scan.nonNfc[0]}); prefer ASCII file names.`);
  }
}
